// Generates the browser build of the xCBase engine from the Node sources (one source of truth).
//   node scripts/xcbase-sync-core.cjs           write web/js/xcbase/core/xcb-core.js and xcb-data.js
//   node scripts/xcbase-sync-core.cjs --check   exit 1 when the generated files are out of date
// Result: window.XCB = { D: dbcore, F: xcdformat, IO: xcdio, C: calccore }. xcdsqlite.cjs is Node only and is not bundled.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), out = path.join(root, 'web', 'js', 'xcbase', 'core');
const MODULES = ['calccore.cjs', 'dbcore.cjs', 'xcdformat.cjs', 'xcdio.cjs'];

const SHIM = `const __mods = {}, __defs = {};
function __def(name, fn) { __defs[name] = fn; }
function __require(name) {
  const n = name.replace(/^.*\\//, '');
  if (!__mods[n]) {
    if (!__defs[n]) throw new Error('module not bundled: ' + name);
    const m = { exports: {} }; __mods[n] = m; __defs[n](m, m.exports, __require);
  }
  return __mods[n].exports;
}
`;

function core() {
  let s = '// GENERATED by scripts/xcbase-sync-core.cjs from tools/*.cjs - do not edit.\n(function (global) {\n\'use strict\';\n' + SHIM;
  for (const m of MODULES) s += '__def(' + JSON.stringify(path.basename(m)) + ', function (module, exports, require) {\n' + fs.readFileSync(path.join(root, 'tools', m), 'utf8').replace(/\r\n/g, '\n').replace(/^#!.*\n/, '') + '\n});\n';
  return s + 'global.XCB = { D: __require("dbcore.cjs"), F: __require("xcdformat.cjs"), IO: __require("xcdio.cjs"), C: __require("calccore.cjs") };\n})(typeof window !== "undefined" ? window : globalThis);\n';
}

function data() {
  const font4 = JSON.parse(fs.readFileSync(path.join(root, 'tools', 'acwriter', 'font4.json'), 'utf8'));
  return '// GENERATED by scripts/xcbase-sync-core.cjs - ACWriter 4x7 font (ASCII 32..127, 7 rows of 4 bits) used by the xCBase Atari view.\n' +
    'window.XCB_DATA = ' + JSON.stringify({ font4 }) + ';\n';
}

const files = { 'xcb-core.js': core(), 'xcb-data.js': data() };
if (process.argv.includes('--check')) {
  const bad = Object.keys(files).filter((f) => !fs.existsSync(path.join(out, f)) || fs.readFileSync(path.join(out, f), 'utf8') !== files[f]);
  if (bad.length) { console.error('out of date: ' + bad.join(', ') + ' (run node scripts/xcbase-sync-core.cjs)'); process.exit(1); }
  console.log('xcbase core up to date');
} else {
  fs.mkdirSync(out, { recursive: true });
  for (const f of Object.keys(files)) fs.writeFileSync(path.join(out, f), files[f]);
  console.log('wrote ' + Object.keys(files).map((f) => f + ' (' + files[f].length + ')').join(', '));
}
